window.I18N_DATA = {"lang":"es","ui":{"tagline":"Primer semestre tras el traslado. Las decisiones después de clase cambian la distancia entre tú y ellas.","nameLabel":"Nombre del protagonista","newGame":"Nueva partida","continue":"Continuar","gallery":"Galería","notice":"Un drama escolar apto para mayores de 15 años. Una partida dura unos 40–70 minutos. 7 finales.","updateNotice":"Actualización: se ha añadido la historia del día del festival (Day 5). Las partidas en curso de la versión anterior se reiniciarán, pero la galería y los finales vistos se conservan.","save":"Guardar","load":"Cargar","backlog":"Historial","auto":"Auto","autoOn":"Auto act.","skip":"Saltar","skipOn":"Saltando","continueChapter":"Continuar","close":"Cerrar","back":"Volver","galleryView":"Ver galería","toTitle":"Ir al título","restart":"Empezar de nuevo","lockedScene":"Escena aún no vista","noRecord":"No hay registros.","endingsSeen":"Finales vistos: {n} / 7","savePrompt":"Escribe el número de ranura para guardar (1, 2, 3)","loadPrompt":"Escribe el número de ranura para cargar (1, 2, 3)","savedMsg":"Guardado en la ranura {slot}.","noSaveMsg":"No hay ninguna partida guardada. En la versión actualizada, las partidas anteriores se han reiniciado.","noSlotMsg":"Esa ranura no tiene ninguna partida guardada. En la versión actualizada, las partidas anteriores se han reiniciado.","finalAff":"Afinidad final: Seoyeon {sv} / Chaerin {cv} / Arin {av}","defaultName":"Dohyun Kim","endingFallback":"Final","intro":"Una historia sobre los cinco días después de clase del primer trimestre en una escuela nueva. Seoyeon Han, delegada; Chaerin Moon, del comité de la biblioteca; y Arin Noh, del club de radio. Las elecciones llevan a siete finales.","autosaveHint":"Continuar carga el autoguardado, que se conserva cada 5 segundos aproximadamente. Es aparte de las tres ranuras.","settings":"Ajustes","toTitleShort":"Título","textSpeed":"Velocidad del texto","autoWait":"Espera del auto","speedSlow":"Lenta","speedNormal":"Normal","speedFast":"Rápida","waitShort":"Corta","waitNormal":"Normal","waitLong":"Larga","emptySlot":"Ranura vacía","slotLabel":"Ranura {n}","overwriteAsk":"¿Sobrescribir este guardado?","overwriteYes":"Sobrescribir","cancel":"Cancelar","dayPrologue":"Prólogo","dayNum":"Day {n}","dayNight":"Day {n} · Noche","dayEnding":"Final","choiceLabel":"Elección","titleConfirm":"¿Volver al título?","titleConfirmBody":"El progreso se autoguarda.","leaveYes":"Volver","previewEmpty":"Sin línea","linkAbout":"Introducción","linkChars":"Personajes","linkContact":"Contacto","linkPrivacy":"Privacidad"},"sp":{"나":"Yo","서연":"Seoyeon","채린":"Chaerin","아린":"Arin","선생님":"Profesor","학생":"Estudiante"},"chapters":{"N1_01":"Day 1 · La noche","N2_01":"Day 2 · La noche","N3_01":"Day 3 · La noche","D1_01_01":"Day 1 · Primer día en la escuela nueva","D2_01_01":"Day 2 · Distancias que se acortan","D3_01_01":"Day 3 · Preparativos del festival","D4_01_01":"Day 4 · La víspera del festival","D5_01_01":"Day 5 · El día del festival"},"endings":{"SY_GOOD":"Final bueno de Seoyeon: Después de clase, contigo","SY_NORMAL":"Final normal de Seoyeon: Las reglas no cambian","CH_GOOD":"Final bueno de Chaerin: El asiento junto a la ventana, para dos","CH_NORMAL":"Final normal de Chaerin: Una relación que se lee despacio","AR_GOOD":"Final bueno de Arin: No es una reserva, es una confirmación","AR_NORMAL":"Final normal de Arin: Un registro oficial","SOLO":"Final en solitario: Adaptación completada"},"endingShort":{"SY_GOOD":"Seoyeon · Bueno","SY_NORMAL":"Seoyeon · Normal","CH_GOOD":"Chaerin · Bueno","CH_NORMAL":"Chaerin · Normal","AR_GOOD":"Arin · Bueno","AR_NORMAL":"Arin · Normal","SOLO":"En solitario"},"cg":{"cg01":"Frente a la puerta del aula, la primera mirada","cg02":"Biblioteca, a un paso de tocarse","cg03":"Bajo el atardecer, un gracias tardío","cg04":"Emisión del festival, unos auriculares que pasan de mano","cg05":"Clausura, el atardecer de los tres"},"steps":{"P01_01":{"tx":"Primavera, mi primer día en la escuela nueva.","sp":"Yo"},"P01_02":{"tx":"La mañana en este barrio al que acabo de mudarme todavía me resulta extraña.","sp":"Yo"},"P01_03":{"tx":"Siguiendo un camino donde vuelan pétalos de cerezo, la puerta de mi nueva escuela se acerca.","sp":"Yo"},"P01_04":{"tx":"La verdad, estoy un poco nervioso.","sp":"Yo"},"P01_05":{"tx":"Una clase nueva, un pupitre nuevo, gente nueva.","sp":"Yo"},"P01_06":{"tx":"Cruzo la puerta con una sola idea: pasar el día de hoy sin problemas.","sp":"Yo"},"P01_07":{"tx":"Frente a los casilleros, vuelvo a revisar la lista de clases.","sp":"Yo"},"P01_08":{"tx":"Segundo año, clase 1. Es la segunda aula desde el final del pasillo.","sp":"Yo"},"P02_01":{"tx":"Frente a la puerta del aula. Respiro hondo y estoy a punto de abrirla.","sp":"Yo"},"P02_02":{"tx":"La puerta se abre antes desde dentro.","sp":"Yo"},"P02_03":{"tx":"Una chica con una carpeta en brazos. Nuestras miradas se cruzan de frente.","sp":"Yo"},"P02_04":{"tx":"Eh... ¿Eres el alumno nuevo?","sp":"Seoyeon"},"P02_05":{"tx":"Pelo largo castaño oscuro. Uniforme impecable. Y unos ojos que miran directamente.","sp":"Yo"},"P02_06":{"tx":"Eso es. Soy Han Seoyeon, la delegada de segundo año, clase 1.","sp":"Seoyeon"},"P02_07":{"tx":"Hoy me encargo yo de acompañarte en tu primer día.","sp":"Seoyeon"},"P02_08":{"choices":["Saludar primero con educación","Comprobar su placa con el nombre y saludar"]},"P02_09":{"tx":"Hola, soy {name}. Cuento contigo hoy.","sp":"Protagonista"},"P02_10":{"tx":"Puedes hablarme de tú. Estamos en la misma clase.","sp":"Seoyeon"},"P02_11":{"tx":"Pero antes de perderte, ven a buscarme a mí primero. Es la regla.","sp":"Seoyeon"},"P02_12":{"tx":"«La regla», dice. Muy de delegada. Pero, por alguna razón, no da miedo.","sp":"Yo"},"P03_01":{"tx":"Bien, os presento al alumno que se une hoy a nuestra clase.","sp":"Profesor"},"P03_02":{"tx":"Frente a la tarima. Todas las miradas de la clase caen sobre mí a la vez.","sp":"Yo"},"P03_03":{"choices":["Presentarme de forma breve y clara","Presentarme con una broma ligera"]},"P03_04":{"tx":"Soy {name}. Espero que nos llevemos bien.","sp":"Protagonista"},"P03_05":{"tx":"También fue Seoyeon quien me indicó mi sitio.","sp":"Yo"},"P03_06":{"tx":"Tu sitio es el segundo empezando por atrás, junto a la ventana. Los libros de texto los recogemos juntos antes de comer.","sp":"Seoyeon"},"P03_07":{"tx":"Así empezó mi primer día tras el traslado.","sp":"Yo"},"D1_01_01":{"tx":"Primera clase. Pero dicen que los libros de texto se reparten por la tarde.","sp":"Yo"},"D1_01_02":{"tx":"Estoy mirando mi pupitre vacío cuando, desde al lado, un libro se desliza en silencio hacia mí.","sp":"Yo"},"D1_01_03":{"tx":"Hoy mira con el mío. Total, los apuntes los tomo todos yo.","sp":"Seoyeon"},"D1_01_04":{"tx":"La mano que abre el libro por la mitad está acostumbrada. Es la mano de alguien acostumbrado a cuidar de otros.","sp":"Yo"},"D1_01_05":{"choices":["Darle las gracias y mirar el libro con ella","Decir que no hace falta y aguantar solo"]},"D1_01_06":{"tx":"Cuando acabe la clase, hazle una foto a mis apuntes. Esa es tu tarea de hoy.","sp":"Seoyeon"},"D1_01_07":{"tx":"En mi primera clase me fijé más en la letra pequeña del asiento de al lado que en las explicaciones del profesor.","sp":"Yo"},"D1_02_01":{"tx":"Hora de comer. Por el altavoz del centro suena una voz alegre.","sp":"Yo"},"D1_02_02":{"tx":"Emisión de mediodía, noticias de hoy. ¡Dicen que ha llegado un alumno nuevo a nuestro centro!","sp":"Arin"},"D1_02_03":{"tx":"Es {name}, de segundo año, clase 1. El club de radio reserva su primera entrevista.","sp":"Arin"},"D1_02_04":{"tx":"Las miradas de la clase vuelven a caer sobre mí. ¿Quién es la dueña de esa voz?","sp":"Yo"},"D1_02_05":{"tx":"Al terminar la emisión, me la encuentro frente a la sala de radio, al final del pasillo.","sp":"Yo"},"D1_02_06":{"tx":"¡Te encontré! Eres el senpai nuevo, ¿verdad?","sp":"Arin"},"D1_02_07":{"tx":"Soy Noh Arin, de primero, del club de radio. La voz de la emisión de mediodía era yo.","sp":"Arin"},"D1_02_08":{"tx":"Tienes la cara tensa. Sonríe, sonríe. Las entrevistas no dan miedo.","sp":"Arin"},"D1_02_09":{"choices":["Aceptar la entrevista con una sonrisa","Pedirle que por hoy me perdone"]},"D1_02_10":{"tx":"Me gusta esa reacción. Algún día la usaré seguro como mi entrevista número uno.","sp":"Arin"},"D1_02_11":{"tx":"Fue una hora de comer en la que hasta una alumna a la que acababa de conocer me hizo una reserva.","sp":"Yo"},"D1_03_01":{"tx":"Después de clase. Pasé por la biblioteca a recoger la lista de libros recomendados que necesito para los papeles del traslado.","sp":"Yo"},"D1_03_02":{"tx":"Entre las estanterías altas, junto a la ventana, una alumna mayor de pelo largo lee un libro.","sp":"Yo"},"D1_03_03":{"tx":"Encontré el primer libro de la lista. Al estirar la mano, desde el otro lado otra mano estuvo a punto de tocar el mismo libro.","sp":"Yo"},"D1_03_04":{"tx":"Dos manos se detienen sobre el libro. Las miradas no van al libro, sino el uno al otro.","sp":"Yo"},"D1_03_05":{"tx":"......¿Buscabas este libro?","sp":"Chaerin"},"D1_03_06":{"tx":"Soy Moon Chaerin, de tercero. Estoy en el comité de biblioteca.","sp":"Chaerin"},"D1_03_07":{"choices":["Decir el título del libro y pedir ayuda","Seguir buscando solo entre las estanterías"]},"D1_03_08":{"tx":"Eres el primer alumno nuevo que elige este libro. La lista... te ayudo yo a completarla.","sp":"Chaerin"},"D1_03_09":{"tx":"A cambio, una cosa. No te conviertas en alguien que empieza a leer por la última página.","sp":"Chaerin"},"D1_03_10":{"tx":"Una biblioteca silenciosa. Pero esa frase se me queda resonando mucho rato en los oídos.","sp":"Yo"},"D1_04_01":{"tx":"En el pasillo, antes de irme. Surgió sin más una encrucijada: ¿con quién cierro el día de hoy?","sp":"Yo"},"D1_04_02":{"choices":["Ordenar el tablón de la clase con Seoyeon","Terminar de elegir la lista de libros recomendados con Chaerin","Aceptar la petición de entrevista de Arin"]},"D1_04_S1":{"tx":"¿Que vas a ayudarme a ordenar el tablón? Vaya, trabajando desde el primer día.","sp":"Seoyeon"},"D1_04_S2":{"tx":"......Gracias. La verdad, era bastante cantidad.","sp":"Seoyeon"},"D1_04_S3":{"tx":"Al repartirlo entre dos, terminamos enseguida. Los hombros de la delegada parecen un poco más ligeros.","sp":"Yo"},"D1_04_C1":{"tx":"El resto de la lista se elige según el gusto de cada uno. ¿Cuál es el tuyo?","sp":"Chaerin"},"D1_04_C2":{"tx":"Esa respuesta no está mal. Mañana entrarán novedades en el buzón de devoluciones. Puedes venir a echar un vistazo.","sp":"Chaerin"},"D1_04_C3":{"tx":"Salgo de la biblioteca abrazando tres libros. Más que la lista, lo que me pesa es lo que dijo la alumna mayor.","sp":"Yo"},"D1_04_A1":{"tx":"Ahora sí, entrevista de verdad. Primera pregunta: ¿quién es la persona que más recuerdas de tu primer día?","sp":"Arin"},"D1_04_A2":{"tx":"Eh, esa respuesta de ahora... la guardo para mi colección personal. Prohibido emitirla.","sp":"Arin"},"D1_04_A3":{"tx":"Ni yo mismo sé qué he dicho. Solo sé que la alumna menor tenía las orejas un poco rojas.","sp":"Yo"},"D2_01_01":{"tx":"Mañana del segundo día. De camino al centro, una voz familiar me llama por detrás.","sp":"Yo"},"D2_01_02":{"tx":"Senpai, la emisión de ayer tuvo buena acogida. Dicen que llegaron consultas sobre el avance de tu entrevista.","sp":"Arin"},"D2_01_03":{"tx":"Así que no puedes escapar. La entrevista número uno es mía.","sp":"Arin"},"D2_01_04":{"choices":["Decirle con sinceridad qué me pareció","Disimular por vergüenza"]},"D2_01_05":{"tx":"Me dio un poco de vergüenza. Pero no estuvo mal.","sp":"Protagonista"},"D2_01_06":{"tx":"Arin asiente satisfecha y sale corriendo delante de mí. Una alumna menor muy ocupada.","sp":"Yo"},"D2_02_01":{"tx":"En clase anuncian un trabajo en grupo.","sp":"Yo"},"D2_02_02":{"tx":"La búsqueda de material la hago yo, la organización... también yo. Y el texto de la presentación, también.","sp":"Seoyeon"},"D2_02_03":{"tx":"Esa manía de cargarlo todo ella sola. La misma imagen que vi ayer en el tablón.","sp":"Yo"},"D2_02_04":{"choices":["Pedirle primero que reparta las tareas","Esperar a que Seoyeon termine de organizarlo"]},"D2_02_05":{"tx":"......Repartir las cosas. Era algo tan obvio, ¿verdad?","sp":"Seoyeon"},"D2_02_06":{"tx":"Entonces, ¿puedo pedirte el borrador de la presentación? Esta vez soy yo quien te pide algo.","sp":"Seoyeon"},"D2_02_07":{"tx":"Fue una clase en la que vi, desde el asiento de al lado, cómo la delegada aprendía a pedir ayuda.","sp":"Yo"},"D2_03_01":{"tx":"Hora de comer, zona de descanso frente a la biblioteca. Chaerin tiene en la mano el libro que se llevó ayer.","sp":"Yo"},"D2_03_02":{"tx":"Ese libro de ayer, El primer camino. En la página 12 hay una frase así.","sp":"Chaerin"},"D2_03_03":{"tx":"«En un camino que recorres por primera vez, las huellas de otro son tu mapa».","sp":"Chaerin"},"D2_03_04":{"tx":"Me pareció una frase que le va bien a un alumno nuevo como tú.","sp":"Chaerin"},"D2_03_05":{"choices":["Repetirle la frase de memoria y preguntarle","Decir con sinceridad que no la recuerdo"]},"D2_03_06":{"tx":"......La recuerdes o seas sincero. Ninguna de las dos es una mala respuesta.","sp":"Chaerin"},"D2_03_07":{"tx":"La alumna mayor me tiende un marcapáginas. Es un marcapáginas de cuero, ya gastado.","sp":"Yo"},"D2_03_08":{"tx":"Te lo presto. Cuando lo termines de leer, ven a devolvérmelo.","sp":"Chaerin"},"D2_04_01":{"tx":"Después de clase. Hoy también me espera una encrucijada en el pasillo.","sp":"Yo"},"D2_04_02":{"choices":["Ordenar con Seoyeon las actas de la reunión del festival","Ayudar a Chaerin a colocar las novedades en la biblioteca","Ser el compañero de práctica de entrevistas de Arin"]},"D2_04_S1":{"tx":"Faltan tres días para el festival. Las actas son una montaña. Venías con eso en mente, ¿verdad?","sp":"Seoyeon"},"D2_04_S2":{"tx":"Al hacerlo entre dos, es la mitad, en tiempo y en trabajo. Es una sensación extraña, en el buen sentido.","sp":"Seoyeon"},"D2_04_S3":{"tx":"En la última página de las actas, Seoyeon escribe en pequeño: «La próxima reunión, entre dos».","sp":"Yo"},"D2_04_C1":{"tx":"Colocar las novedades es un trabajo que se hace en silencio. A ti te pega el silencio.","sp":"Chaerin"},"D2_04_C2":{"tx":"El asiento junto a la ventana era para mí sola. Pero siento como si al lado hubiera una estantería más.","sp":"Chaerin"},"D2_04_C3":{"tx":"Antes de poder preguntarle qué significa, la alumna mayor se da la vuelta. La respuesta la buscaré mañana.","sp":"Yo"},"D2_04_A1":{"tx":"Práctica de entrevista, solo tres preguntas. ¿Quién es la persona en la que más piensas últimamente?","sp":"Arin"},"D2_04_A2":{"tx":"......Esa pregunta ha sido un error mío. Haré como que no he oído la respuesta. Me la quedo solo yo.","sp":"Arin"},"D2_04_A3":{"tx":"La práctica terminó ahí. En el cuaderno de la alumna menor había algo escrito, bastante largo.","sp":"Yo"},"D3_01_01":{"tx":"Tercer día. En la reunión de la mañana anuncian el calendario del festival.","sp":"Yo"},"D3_01_02":{"tx":"Los preparativos del festival se harán por parejas en cada clase. Confirmad vuestra pareja antes de la víspera del festival.","sp":"Profesor"},"D3_01_03":{"tx":"Yo recojo las solicitudes de pareja. Si alguien está dudando... también puede consultarme.","sp":"Seoyeon"},"D3_01_04":{"tx":"Aviso de la radio. Las solicitudes para presentador de la emisión del festival se recogen en el club de radio.","sp":"Arin"},"D3_01_05":{"tx":"Pareja para el festival. A los tres días del traslado ya hay cosas que tengo que decidir.","sp":"Yo"},"D3_02_01":{"tx":"Al terminar las clases fui a la biblioteca a devolver el marcapáginas.","sp":"Yo"},"D3_02_02":{"tx":"Has venido en buen momento. La verdad es que ha desaparecido un libro del buzón de devoluciones.","sp":"Chaerin"},"D3_02_03":{"tx":"Es un libro que guardaba para la exposición del festival. Si lo busco sola, tardaré mucho.","sp":"Chaerin"},"D3_02_04":{"choices":["Decir que lo buscamos juntos","Decir que avisemos al comité de biblioteca"]},"D3_02_05":{"tx":"Gracias. Solo hay una pista. Probablemente esté cerca de las estanterías donde colocamos las novedades ayer.","sp":"Chaerin"},"D3_02_06":{"tx":"La búsqueda del libro acabaría alargándose hasta después de clase.","sp":"Yo"},"D3_03_01":{"tx":"Hora de comer. Hay alboroto frente a la sala de radio.","sp":"Yo"},"D3_03_02":{"tx":"Senpai, es un desastre. El orden del guion de la emisión está todo mezclado.","sp":"Arin"},"D3_03_03":{"tx":"Faltan cinco minutos para la emisión. Yo... es la primera vez que meto la pata así.","sp":"Arin"},"D3_03_04":{"choices":["Ordenar el guion con ella y ajustar el orden","Decir que voy a llamar a un profesor"]},"D3_03_05":{"tx":"Ya está, el orden cuadra. De la emisión me encargo yo. Tú quédate a mi lado y mírame.","sp":"Arin"},"D3_03_06":{"tx":"La alumna menor enciende el micrófono con manos temblorosas. La emisión terminó sin problemas.","sp":"Yo"},"D3_03_07":{"tx":"Después de clase hay una regrabación. Entonces te daré las gracias como es debido.","sp":"Arin"},"D3_04_01":{"tx":"Después de clase. El plazo para confirmar la pareja del festival es mañana, la víspera.","sp":"Yo"},"D3_04_02":{"tx":"Tengo que decidir a dónde ir. Ya es el momento.","sp":"Yo"},"D3_04_03":{"choices":["Ayudar a Seoyeon con los papeles del festival hasta el final","Buscar el libro perdido con Chaerin hasta encontrarlo","Ayudar a Arin con la regrabación y fijar la promesa"]},"D3_04_S1":{"tx":"Hay tres cajas de documentos. ¿Crees que podremos terminarlas hoy, entre los dos?","sp":"Seoyeon"},"D3_04_S2":{"tx":"He dicho «nosotros», ¿verdad? ......No vale echarse atrás.","sp":"Seoyeon"},"D3_04_S3":{"tx":"Cuando terminamos de ordenar todos los papeles, fuera de la ventana ya brillaba el atardecer.","sp":"Yo"},"D3_04_C1":{"tx":"Empecemos por la parte de atrás de las estanterías. Sin hacer ruido, y recordando el orden de colores de los lomos.","sp":"Chaerin"},"D3_04_C2":{"tx":"Lo hemos encontrado, aquí está. Ya decía yo que buscar entre dos es más rápido.","sp":"Chaerin"},"D3_04_C3":{"tx":"La expresión de la alumna mayor abrazando el libro encontrado fue la más suave de todas las que vi hoy.","sp":"Yo"},"D3_04_A1":{"tx":"Última pregunta de la regrabación. ¿Con quién quieres pasar el festival?","sp":"Arin"},"D3_04_A2":{"tx":"Esa respuesta no es para la emisión. La anoto como una promesa, en mi cuaderno.","sp":"Arin"},"D3_04_A3":{"tx":"La alumna menor escribe algo en su cuaderno con letra cuidada. Alcancé a ver dos palabras: «una promesa».","sp":"Yo"},"D5_01_01":{"tx":"La mañana del día del festival. Al cruzar la puerta noto enseguida un aire distinto al de ayer.","sp":"Yo"},"D5_01_02":{"tx":"En los bordes del patio ya están alineadas las carpas de los puestos, y las pancartas ondean con el viento.","sp":"Yo"},"D5_01_03":{"tx":"Todos los papeles y ensayos acumulados hasta ayer eran para hoy.","sp":"Yo"},"D5_01_04":{"tx":"Aviso informativo. En breve, a las nueve, comenzará la ceremonia de apertura del festival.","sp":"Arin"},"D5_01_05":{"tx":"La voz de Arin a través del altavoz suena mucho más firme que en el ensayo de ayer.","sp":"Yo"},"D5_01_06":{"tx":"{name}, has venido pronto. Antes de la apertura, ¿me acompañas a revisar los puestos una vuelta?","sp":"Seoyeon"},"D5_01_07":{"tx":"La delegada, con su lista de revisión y un bolígrafo. Hoy también lleva los hombros un poco subidos.","sp":"Yo"},"D5_01_08":{"tx":"Aun así, hoy estoy menos nerviosa que ayer. Quizá porque a mi lado hay una cara conocida.","sp":"Seoyeon"},"D5_01_09":{"tx":"De camino entre los puestos pasamos frente al cartel de la exposición de libros. En el sitio del primer libro hay una pequeña nota escrita a mano.","sp":"Yo"},"D5_01_10":{"tx":"«La primera página se abre entre dos». Una frase muy propia de Chaerin.","sp":"Yo"},"D5_01_11":{"tx":"Del lado del puesto de radio, Arin me saluda con la mano. La tarjeta de miembro que lleva al cuello brilla con el sol.","sp":"Yo"},"D5_01_12":{"tx":"Suena la campana de apertura. El festival ha comenzado.","sp":"Yo"},"D5_01_13":{"choices":["Dar una vuelta para empaparme del ambiente de apertura","Visitar primero el puesto más cercano","Respirar hondo y repasar el plan del día"]},"D5_02_01":{"tx":"Treinta minutos tras la apertura. Frente al puesto de limonada de la clase 1 ya hay una fila larga.","sp":"Yo"},"D5_02_02":{"tx":"Recibo los pedidos en orden. No hay prisa.","sp":"Seoyeon"},"D5_02_03":{"tx":"Su voz es tranquila, pero la mano que sostiene los pedidos no para de moverse.","sp":"Yo"},"D5_02_04":{"tx":"Oiga, la limonada todavía no. Llevo esperando desde hace un rato.","sp":"Estudiante"},"D5_02_05":{"tx":"En plena hora punta, dos pedidos se han mezclado. Al final de la fila crece el murmullo.","sp":"Yo"},"D5_02_06":{"tx":"Lo siento. Lo compruebo ahora mismo. Espere un momento, por favor.","sp":"Seoyeon"},"D5_02_07":{"choices":["Ponerme al final de la fila y anunciar el orden con calma","Desplegar los pedidos junto a Seoyeon, a su lado"]},"D5_02_08":{"tx":"Al reordenar los pedidos por hora, el murmullo de la fila se apaga.","sp":"Yo"},"D5_02_09":{"tx":"Ya hemos cogido el ritmo. A partir del siguiente pedido no habrá retrasos.","sp":"Seoyeon"},"D5_02_10":{"tx":"El puesto ha recuperado su ritmo, pero Seoyeon sigue sin descansar ni una sola vez.","sp":"Yo"},"D5_02_11":{"tx":"Se superpone la imagen de ayer, enterrada bajo la montaña de papeles. Su manía de acumular peticiones sin pedir ayuda sigue igual.","sp":"Yo"},"D5_02_12":{"tx":"{name}, ve a tu siguiente compromiso. Aquí ya está todo bien.","sp":"Seoyeon"},"D5_02_13":{"tx":"A pesar de sus palabras, al final de su voz hay un temblor mínimo.","sp":"Yo"},"D5_02_14":{"tx":"Podría darme la vuelta y marcharme sin más. Pero me viene a la mente la delegada que ayer aprendía a apoyarse en otros.","sp":"Yo"},"D5_02_15":{"choices":["Ayudarla a su lado hasta que la fila se despeje","Creer las palabras de Seoyeon e ir al siguiente compromiso"]},"D5_02_16":{"tx":"......De verdad, si sigues dándote cuenta antes que nadie... Hoy seré yo quien diga primero «gracias».","sp":"Seoyeon"},"D5_03_01":{"tx":"La biblioteca a la hora de comer. Como es el último día de la exposición del festival, hay más gente de lo habitual.","sp":"Yo"},"D5_03_02":{"tx":"En el centro de la exposición está ese libro que hace unos días desapareció del buzón de devoluciones y luego apareció.","sp":"Yo"},"D5_03_03":{"tx":"El libro que se había perdido está en el sitio más popular. Irónico, ¿verdad?","sp":"Chaerin"},"D5_03_04":{"tx":"¿Por qué eligió este libro como el primero de la exposición?","sp":"Estudiante"},"D5_03_05":{"tx":"Las preguntas de los visitantes llegan todas a la vez. El motivo de la recomendación, cosas del autor, los planes para la próxima exposición.","sp":"Yo"},"D5_03_06":{"tx":"Responderé una a una. Las historias de libros, si se cuentan con prisa, pierden la gracia.","sp":"Chaerin"},"D5_03_07":{"choices":["Ordenar el orden de las preguntas y pasárselo a la alumna mayor","Ponerme a su lado sosteniendo el cartel de la exposición"]},"D5_03_08":{"tx":"Cuando las preguntas se ordenan, las respuestas de la alumna mayor se hacen más largas. Es una persona que habla más cuando el tema es un libro.","sp":"Yo"},"D5_03_09":{"tx":"La última página de este libro... cada lector la recuerda de una forma distinta.","sp":"Chaerin"},"D5_03_10":{"tx":"Un visitante asiente y abre el libro. La sala de exposición parece ya una pequeña reunión de lectura.","sp":"Yo"},"D5_03_11":{"tx":"Las preguntas han amainado, pero en el asiento junto a la ventana de la alumna mayor aún queda la hoja de preguntas del siguiente visitante.","sp":"Yo"},"D5_03_12":{"tx":"La exposición es hasta la tarde. Yo me quedaré aquí, vigilándola hasta el final.","sp":"Chaerin"},"D5_03_13":{"tx":"Es el tono de alguien acostumbrado a vigilar en solitario. Pero hoy suena algo distinto.","sp":"Yo"},"D5_03_14":{"tx":"El marcapáginas no está en el cajón de mi pupitre, sino en la mochila que he traído hoy. Devolvérselo toca después de que acabe el festival.","sp":"Yo"},"D5_03_15":{"choices":["Atender junto a ella hasta el último visitante","Confiar en su ritmo y dejar el sitio libre"]},"D5_03_16":{"tx":"......Quitarme las gafas para hablar solo lo hago cuando quiero concentrarme. Hoy había un motivo para hacerlo.","sp":"Chaerin"},"D5_04_01":{"tx":"Justo antes de la emisión en directo de la tarde. Al abrir la puerta de la sala de radio, Arin se acerca agitando el guion.","sp":"Yo"},"D5_04_02":{"tx":"Senpai, mira esto. En la última línea del guion están escritos, uno junto al otro, los nombres de los dos presentadores, ¿ves?","sp":"Arin"},"D5_04_03":{"tx":"En el hueco que ayer estaba vacío, hoy está escrito mi nombre con letra cuidada.","sp":"Yo"},"D5_04_04":{"tx":"El hueco lo rellené yo esta mañana. Con tinta, para que no puedas escapar.","sp":"Arin"},"D5_04_05":{"tx":"Vamos, empieza la emisión. La presentación de la primera canción va como la preparamos ayer: empiezas tú, senpai.","sp":"Arin"},"D5_04_06":{"tx":"Se enciende la luz de «en el aire». Empieza la conexión que ensayamos tantas veces.","sp":"Yo"},"D5_04_07":{"tx":"Pero cuando terminaba la segunda canción, por el altavoz estalló un ruido agudo.","sp":"Yo"},"D5_04_08":{"tx":"Eh, el archivo de sonido se ha cruzado. Esto es un fallo de emisión.","sp":"Arin"},"D5_04_09":{"choices":["Ganar tiempo hablando y hacerle una señal a Arin","Abrir el siguiente segmento siguiendo el orden de emergencia del guion"]},"D5_04_10":{"tx":"Nunca pensé que el orden de emergencia que fijamos ayer entre risas se usaría de verdad.","sp":"Yo"},"D5_04_11":{"tx":"Archivo recuperado. Tu voz no ha temblado ni un poco, senpai.","sp":"Arin"},"D5_04_12":{"tx":"La emisión se reanudó sin problemas. Solo quedan el último segmento y el cierre.","sp":"Yo"},"D5_04_13":{"tx":"El cierre puedo hacerlo yo sola. Tú tienes otro compromiso después, ¿no?","sp":"Arin"},"D5_04_14":{"tx":"Habla con alegría, pero las yemas de sus dedos aún retienen la tensión del fallo de hace un momento.","sp":"Yo"},"D5_04_15":{"choices":["Terminar con ella hasta el cierre, en el asiento de al lado","Confiar en la presentación de Arin y salir de la sala de radio"]},"D5_04_16":{"tx":"No me arrepiento de haber rellenado el hueco. Esta emisión va a ser la que más recuerde.","sp":"Arin"},"D5_05_01":{"tx":"Antes de la actuación de la tarde en el escenario, la gente empieza a reunirse en el patio.","sp":"Yo"},"D5_05_02":{"tx":"Pero del altavoz del escenario no sale sonido. Parece que un cable está mal conectado.","sp":"Yo"},"D5_05_03":{"tx":"Faltan veinte minutos para que empiece la actuación. Primero ordenaré el paso del público.","sp":"Seoyeon"},"D5_05_04":{"tx":"Yo puliré el aviso del retraso. Para que el tiempo de espera se haga más corto.","sp":"Chaerin"},"D5_05_05":{"tx":"Yo meteré un aviso por la radio. Para que nadie se asuste.","sp":"Arin"},"D5_05_06":{"tx":"El cable suelto se encontró enseguida detrás del escenario. El problema es lo siguiente: ¿con quién remato el trabajo?","sp":"Yo"},"D5_05_07":{"tx":"Las miradas de las tres se cruzan una vez. Es el momento en que la tarde del festival se divide.","sp":"Yo"},"D5_05_08":{"choices":["Ordenar el paso del escenario junto a Seoyeon","Pulir el aviso del retraso junto a Chaerin","Ajustar la emisión de aviso junto a Arin"]},"D5_05_S1":{"tx":"La entrada por aquí, la salida por el lado contrario. Para que nadie se confunda, pongamos primero los carteles.","sp":"Seoyeon"},"D5_05_S2":{"tx":"Mientras ponemos los carteles y ajustamos la fila, las instrucciones de la delegada no se interrumpen ni una vez.","sp":"Yo"},"D5_05_S3":{"tx":"Con el paso ordenado, también se me ordena la cabeza. Creo que podemos empezar.","sp":"Seoyeon"},"D5_05_S4":{"tx":"Se encienden las luces del escenario. El sonido de los aplausos se extiende por el patio.","sp":"Yo"},"D5_05_S5":{"tx":"Hoy, a mi lado, ha estado todo el día la misma persona. ......No es casualidad, ¿verdad?","sp":"Seoyeon"},"D5_05_C1":{"tx":"La primera frase del aviso, así: que la espera también es parte del festival.","sp":"Chaerin"},"D5_05_C2":{"tx":"La mano de la alumna mayor, que elige las frases, es lenta. Es alguien que le da peso a cada palabra.","sp":"Yo"},"D5_05_C3":{"tx":"La expresión que has elegido tú es más suave. Vamos con esa.","sp":"Chaerin"},"D5_05_C4":{"tx":"El aviso terminado se cuelga en el tablón junto al escenario. Las caras de la gente que espera se relajan un poco.","sp":"Yo"},"D5_05_C5":{"tx":"Es la primera vez que elijo frases junto a alguien. Y no es una mala primera vez.","sp":"Chaerin"},"D5_05_A1":{"tx":"El aviso, ¿y si lo leemos senpai y yo por turnos? Así la espera se hace menos pesada.","sp":"Arin"},"D5_05_A2":{"tx":"Los dos nombres escritos en el hueco del guion, esta vez sí, se leen de verdad uno junto al otro.","sp":"Yo"},"D5_05_A3":{"tx":"Vamos perfectamente compenetrados. Ya decía yo que el hueco era tu sitio, senpai.","sp":"Arin"},"D5_05_A4":{"tx":"Al terminar el aviso, desde el escenario llega la señal de que el cable ya está reparado.","sp":"Yo"},"D5_05_A5":{"tx":"El aviso que hemos leído juntos lo habrá oído todo el centro. Me da un poco de vergüenza, pero me gusta.","sp":"Arin"},"D5_06_01":{"tx":"El sol se inclina y el atardecer se extiende sobre las carpas de los puestos.","sp":"Yo"},"D5_06_02":{"tx":"Aviso de clausura. Gracias a todos por haber venido hoy al festival.","sp":"Arin"},"D5_06_03":{"tx":"El comentario de cierre de Arin resuena por el patio. El guion que empezó con un hueco se leyó hasta el final.","sp":"Yo"},"D5_06_04":{"tx":"Hubo un fallo, pero terminamos sin heridos. Con eso basta.","sp":"Seoyeon"},"D5_06_05":{"tx":"Y hoy creo que he aprendido un poco a apoyarme en alguien. Ahora tengo en quién apoyarme.","sp":"Seoyeon"},"D5_06_06":{"tx":"Antes de que la gente se disperse con los preparativos de la clausura, la luz de la exposición de la biblioteca también se apagará pronto.","sp":"Yo"},"D5_06_07":{"tx":"Saco de la mochila el marcapáginas de cuero gastado. El festival ha terminado, así que es hora de devolverlo, como prometí.","sp":"Yo"},"D5_06_08":{"tx":"Has venido a devolvérmelo. ¿Recuerdas lo que te dije, que esperar tenía su gracia?","sp":"Chaerin"},"D5_06_09":{"tx":"El marcapáginas ha vuelto a su sitio de siempre. Pero el sitio de la persona que lo tomó prestado... quién sabe.","sp":"Chaerin"},"D5_06_10":{"tx":"Cuando abras el siguiente libro, me gustaría que estuvieras otra vez a mi lado. Hasta entonces, esto lo guardo yo.","sp":"Chaerin"},"D5_06_11":{"tx":"Senpai, ¿qué tal la emisión de hoy? Una impresión, como la persona que rellenó el hueco.","sp":"Arin"},"D5_06_12":{"tx":"En el guion de la próxima emisión también dejaré un hueco. Porque quien lo rellena ya está decidido.","sp":"Arin"},"D5_06_13":{"tx":"Las luces del escenario se apagan una a una. Se pliegan las carpas y se apilan las sillas.","sp":"Yo"},"D5_06_14":{"choices":["Mirar el escenario que se apaga","Mirar la calle de puestos que se recoge","Mirar el cielo donde se pone el atardecer"]},"D5_06_15":{"tx":"Cinco días desde el traslado. La escuela que me era extraña, hoy se siente un poco como mi sitio.","sp":"Yo"},"D5_06_16":{"tx":"Al final del festival, me viene a la mente la cara con la que más tiempo pasé hoy.","sp":"Yo"},"END_SY_G01":{"tx":"Terminada la limpieza de la clausura, Seoyeon propuso subir un momento a las escaleras frente a la azotea a tomar el aire.","sp":"Yo"},"END_SY_G02":{"tx":"Lo de hoy... no, lo de estos cinco días. Menos mal que te pedí ayuda.","sp":"Seoyeon"},"END_SY_G03":{"tx":"A mí me cuesta pedir. Creía que era más cómodo hacerlo todo yo sola.","sp":"Seoyeon"},"END_SY_G04":{"tx":"Pero compartirlo contigo, {name}, no solo reduce el trabajo.","sp":"Seoyeon"},"END_SY_G05":{"tx":"Vi que en la solicitud de pareja del próximo festival ya está escrito mi nombre.","sp":"Protagonista"},"END_SY_G06":{"tx":"......Ese sitio... lo estaba guardando para escribirlo yo primero.","sp":"Seoyeon"},"END_SY_G07":{"tx":"Hoy lo hemos hecho todo entre dos, de principio a fin. El próximo festival, hagámoslo también juntos.","sp":"Seoyeon"},"END_SY_G08":{"tx":"En la solicitud, bajo la luz del atardecer, quedaron escritos uno junto al otro los nombres de los dos.","sp":"Yo"},"END_SY_G09":{"tx":"Final bueno de Seoyeon. Después de clase, contigo.","sp":"Yo"},"END_SY_N01":{"tx":"Gracias por la ayuda de hoy. Ya no hay que preocuparse por tu adaptación.","sp":"Seoyeon"},"END_SY_N02":{"tx":"La pareja del festival la decidí según el calendario de la clase. Sin que ninguno se fuerce.","sp":"Seoyeon"},"END_SY_N03":{"tx":"Una buena compañera de clase. Esa distancia era exactamente la nuestra de ahora.","sp":"Yo"},"END_SY_N04":{"tx":"Si mañana te pierdes, ven a buscarme a mí primero. La regla no cambia.","sp":"Seoyeon"},"END_SY_N05":{"tx":"Final normal de Seoyeon. Las reglas no cambian.","sp":"Yo"},"END_CH_G01":{"tx":"Al devolver el libro encontrado a su estantería, Chaerin me guio hasta el asiento junto a la ventana.","sp":"Yo"},"END_CH_G02":{"tx":"Este sitio es, en principio, para una sola persona. Pero hoy pondré una silla más.","sp":"Chaerin"},"END_CH_G03":{"tx":"La alumna mayor se quita las gafas. Por primera vez, nuestras miradas se encuentran de frente, largo rato.","sp":"Yo"},"END_CH_G04":{"tx":"Dijeron que en un camino nuevo, las huellas de otro son el mapa. Tus huellas... ahora las memorizo yo.","sp":"Chaerin"},"END_CH_G05":{"tx":"La próxima exposición también, preparémosla juntos. La solicitud de pareja de la biblioteca la haré yo primero.","sp":"Chaerin"},"END_CH_G06":{"tx":"Sobre el asiento junto a la ventana ahora hay dos marcapáginas.","sp":"Yo"},"END_CH_G07":{"tx":"Final bueno de Chaerin. El asiento junto a la ventana, para dos.","sp":"Yo"},"END_CH_N01":{"tx":"Gracias por encontrar el libro. La exposición ha terminado sin problemas.","sp":"Chaerin"},"END_CH_N02":{"tx":"El marcapáginas lo he recibido hoy bien. Cuando abramos el próximo libro, volvamos a vernos. Despacio.","sp":"Chaerin"},"END_CH_N03":{"tx":"El trato tranquilo continuará, pero el asiento junto a la ventana seguía siendo para una sola persona.","sp":"Yo"},"END_CH_N04":{"tx":"Final normal de Chaerin. Una relación que se lee despacio.","sp":"Yo"},"END_AR_G01":{"tx":"Terminada la emisión de clausura, Arin abre su cuaderno por la última página y me lo muestra.","sp":"Yo"},"END_AR_G02":{"tx":"Lo escribí aquí. Emisión del festival, presentada junto al senpai {name}.","sp":"Arin"},"END_AR_G03":{"tx":"Y tengo la aprobación del club de radio. Así que esto no es una reserva: es una confirmación.","sp":"Arin"},"END_AR_G04":{"tx":"¿Desde cuándo has montado todo esto tan a lo grande?","sp":"Protagonista"},"END_AR_G05":{"tx":"Ya sabías desde el primer día que yo voy directa. A cambio, las promesas las cumplo siempre.","sp":"Arin"},"END_AR_G06":{"tx":"Al final de la lista de promesas del cuaderno se añadió una más, una promesa que solo conocen dos personas.","sp":"Yo"},"END_AR_G07":{"tx":"Final bueno de Arin. No es una reserva, es una confirmación.","sp":"Yo"},"END_AR_N01":{"tx":"Fin de la emisión del festival. La ayuda de hoy la dejaré anotada como colaboración. Oficialmente.","sp":"Arin"},"END_AR_N02":{"tx":"En la emisión del festival también salió tu voz, senpai. Pero la presentación era mi parte.","sp":"Arin"},"END_AR_N03":{"tx":"Presentadora y entrevistado. La relación no avanzó un paso más desde ahí.","sp":"Yo"},"END_AR_N04":{"tx":"Final normal de Arin. Un registro oficial.","sp":"Yo"},"END_SOLO_01":{"tx":"El festival terminó. Yo corrí de un lado a otro hasta el final, solo, como miembro del comité de preparación.","sp":"Yo"},"END_SOLO_02":{"tx":"Cinco días desde el traslado. Todavía no he hecho ninguna promesa especial con nadie.","sp":"Yo"},"END_SOLO_03":{"tx":"A cambio, ya me sé el mapa de la escuela y las caras del pasillo ya me resultan bastante familiares.","sp":"Yo"},"END_SOLO_04":{"tx":"El festival fue ajetreado. Acercarme a la gente será lo siguiente.","sp":"Yo"},"END_SOLO_05":{"tx":"El semestre de primavera no ha hecho más que empezar. Aún queda mucho tiempo después de clase.","sp":"Yo"},"END_SOLO_06":{"tx":"Final en solitario. Adaptación completada.","sp":"Yo"},"N1_01":{"tx":"Cuando el sol empezaba a inclinarse, de camino a casa sonó mi móvil.","sp":"Yo"},"N1_02":{"tx":"(Mensaje) Gracias por la ayuda de hoy con la guía. Mañana nos vemos en la puerta del centro. No te pierdas, ¿eh?","sp":"Seoyeon"},"N1_03":{"tx":"Escribí una respuesta y la borré dos veces. No era nada especial, pero por alguna razón me importa.","sp":"Yo"},"N1_04":{"choices":["Responder con un mensaje corto","Escribir un mensaje largo diciendo que cuento con ella mañana"]},"N1_05":{"tx":"(Mensaje) Senpai, mañana toca el avance de la entrevista, segunda parte. Prohibido escapar, ¿lo sabes?","sp":"Arin"},"N1_06":{"tx":"Y en la mochila, entre las páginas del libro que me prestó Chaerin, había una notita metida.","sp":"Yo"},"N1_07":{"tx":"(Nota) No empieces a leer por la última página. La promesa, no la olvides.","sp":"Chaerin"},"N1_08":{"tx":"No pensé que el primer día tras el traslado sería tan largo.","sp":"Yo"},"N1_09":{"tx":"Y, sin embargo, de una forma extraña, estoy deseando que llegue mañana.","sp":"Yo"},"N2_01":{"tx":"La noche del segundo día. Me ducho y me acuesto, pero el sueño no llega enseguida.","sp":"Yo"},"N2_02":{"tx":"En el móvil se acumulan notificaciones del grupo de la clase. Todas hablan solo de los preparativos del festival.","sp":"Yo"},"N2_03":{"tx":"(Mensaje) He visto las actas. Mañana lo hacemos repartido. No solo, ¿vale?","sp":"Seoyeon"},"N2_04":{"tx":"«No solo». Esa frase me da vueltas en la cabeza.","sp":"Yo"},"N2_05":{"choices":["Enviar la respuesta enseguida","Pensármelo un buen rato antes de enviarla"]},"N2_06":{"tx":"(Mensaje) Mañana a mediodía, frente a la sala de radio. Es un secreto, solo para ti, senpai.","sp":"Arin"},"N2_07":{"tx":"Al abrir el marcapáginas que tengo sobre el escritorio, me viene a la mente la voz de Chaerin.","sp":"Yo"},"N2_08":{"tx":"(Voz en mi recuerdo) «En un camino que recorres por primera vez, las huellas de otro son tu mapa».","sp":"Chaerin"},"N2_09":{"tx":"Faltan tres días para el festival. Tengo la sensación de que algo está a punto de empezar.","sp":"Yo"},"N3_01":{"tx":"La noche del tercer día. El plazo de las parejas del festival es mañana.","sp":"Yo"},"N3_02":{"tx":"Lo que ha pasado hoy me viene a la cabeza sin orden. El tablón, la biblioteca, la sala de radio.","sp":"Yo"},"N3_03":{"tx":"(Mensaje) Los papeles de mañana, hagámoslos juntos hasta el final. Es una promesa.","sp":"Seoyeon"},"N3_04":{"tx":"(Mensaje) Mañana es la final de la regrabación. La promesa la tengo anotada en mi cuaderno.","sp":"Arin"},"N3_05":{"tx":"(Nota) El libro, mañana, devuélvemelo en el asiento junto a la ventana. Te esperaré.","sp":"Chaerin"},"N3_06":{"tx":"El rostro con el que pasé más tiempo hoy probablemente también estará ahí mañana.","sp":"Yo"},"N3_07":{"choices":["Decidir dormir temprano","Escribir cada respuesta con cuidado, una a una"]},"N3_08":{"tx":"Elija lo que elija, la mañana llegará enseguida.","sp":"Yo"},"N3_09":{"tx":"La víspera del festival. El corazón me late un poco más rápido.","sp":"Yo"},"D4_01_01":{"tx":"La mañana de la víspera del festival. Frente a la puerta del centro ya están colgando las pancartas.","sp":"Yo"},"D4_01_02":{"tx":"Senpai, hoy el ambiente es distinto, ¿verdad? La víspera de un festival cambia el aire.","sp":"Arin"},"D4_01_03":{"choices":["Decir con sinceridad que estoy emocionado","Decir que no es distinto de lo normal"]},"D4_01_04":{"tx":"Todos están animados. Pero el trabajo de hoy es una montaña.","sp":"Seoyeon"},"D4_01_05":{"tx":"Festival, D-1. Cuando acabe el día de hoy, también se decidirá mi pareja.","sp":"Yo"},"D4_02_01":{"tx":"Al terminar las clases, la clase pasa enseguida a modo preparativos del festival.","sp":"Yo"},"D4_02_02":{"tx":"La distribución de los puestos ha cambiado. Hay que rehacer el paso del público. Y tiene que ser hoy.","sp":"Seoyeon"},"D4_02_03":{"tx":"Las manos de Seoyeon son rápidas, pero sus hombros están más subidos que ayer.","sp":"Yo"},"D4_02_04":{"choices":["Decir que me encargo yo de trazar el paso","Ayudar a su lado, a su ritmo"]},"D4_02_05":{"tx":"......Si sigues dándote cuenta antes que nadie, al final me apoyaré en ti, ¿sabes?","sp":"Seoyeon"},"D4_02_06":{"tx":"Entonces... ¿puedo apoyarme? Hoy me apoyaré solo un poco.","sp":"Seoyeon"},"D4_02_07":{"tx":"A la delegada le llevó cuatro días aprender a apoyarse en alguien.","sp":"Yo"},"D4_03_01":{"tx":"Hora de comer. La biblioteca está tranquila pero ajetreada con los preparativos de la exposición del festival.","sp":"Yo"},"D4_03_02":{"tx":"El orden de los libros de la exposición es mi última duda. Porque el primer libro decide la impresión.","sp":"Chaerin"},"D4_03_03":{"tx":"El primer libro que eligió la alumna mayor era ese que el primer día tras el traslado estuvimos a punto de coger juntos.","sp":"Yo"},"D4_03_04":{"choices":["Decir que ese libro es el indicado","Decir que confío en su elección"]},"D4_03_05":{"tx":"La primera página, al fin y al cabo, es mejor abrirla con alguien.","sp":"Chaerin"},"D4_03_06":{"tx":"El marcapáginas que iba a devolver, la alumna mayor lo pone de nuevo en mi mano.","sp":"Yo"},"D4_03_07":{"tx":"Cuando mañana acabe el festival, devuélvemelo entonces. ......Esperar ha empezado a tener su gracia.","sp":"Chaerin"},"D4_03_08":{"tx":"«El gusto de esperar». Con esas palabras, la hora de comer se me hizo corta.","sp":"Yo"},"D4_04_01":{"tx":"Justo antes de terminar las clases. En la sala de radio, el ensayo de la emisión del festival está en pleno apogeo.","sp":"Yo"},"D4_04_02":{"tx":"Senpai, has venido justo a tiempo. Para el guion del ensayo me hacía falta un compañero de diálogo.","sp":"Arin"},"D4_04_03":{"tx":"En la última línea del guion están escritos, uno junto al otro, los nombres de los dos presentadores. Uno de los lados está vacío.","sp":"Yo"},"D4_04_04":{"choices":["Señalar el hueco y preguntar","Leer solo el guion, como si no lo hubiera visto"]},"D4_04_05":{"tx":"Ese hueco, todavía no está confirmado. Mañana... podría rellenarse.","sp":"Arin"},"D4_04_06":{"tx":"Así que mañana no llegues tarde. Porque la primera emisión quiero empezarla contigo.","sp":"Arin"},"D4_04_07":{"tx":"La voz al otro lado del micrófono del ensayo hoy sonó especialmente cercana.","sp":"Yo"},"D4_05_01":{"tx":"Después de clase. La última encrucijada de la víspera del festival.","sp":"Yo"},"D4_05_02":{"tx":"Para el cierre de solicitudes de pareja ya no queda tiempo de verdad.","sp":"Yo"},"D4_05_03":{"choices":["Terminar los últimos papeles con Seoyeon","Rematar los preparativos de la exposición con Chaerin","Ajustar el ensayo final con Arin"]},"D4_05_S1":{"tx":"Los últimos papeles. Cuando acaben, ya solo quedará el festival de verdad.","sp":"Seoyeon"},"D4_05_S2":{"tx":"Mañana te guardaré mi asiento de al lado vacío. Espero que ya esté decidido el nombre que escribirás en la solicitud.","sp":"Seoyeon"},"D4_05_S3":{"tx":"Como corresponde a alguien que se guarda las palabras, esa fue su invitación más sincera.","sp":"Yo"},"D4_05_C1":{"tx":"La exposición está completa. Ahora solo queda con quién la verás mañana.","sp":"Chaerin"},"D4_05_C2":{"tx":"Mañana pondré dos sillas en el asiento junto a la ventana. Vendrás, ¿verdad?","sp":"Chaerin"},"D4_05_C3":{"tx":"En vez de responder, asentí con la cabeza. Los ojos de la alumna mayor sonrieron un poco.","sp":"Yo"},"D4_05_A1":{"tx":"Ensayo final terminado. Nuestra compenetración ha sido perfecta.","sp":"Arin"},"D4_05_A2":{"tx":"La presentación de la primera canción de mañana, me gustaría que empezara con tu voz, senpai. ......Lo harás conmigo, ¿verdad?","sp":"Arin"},"D4_05_A3":{"tx":"El hueco del cuaderno no se me va de la cabeza. Mañana se rellenará.","sp":"Yo"},"P03_04J":{"tx":"Soy {name}. Es mi primer traslado, así que si se ríen, ya es medio éxito."},"P03_04R":{"tx":"......Ese chiste aprueba. Daremos los nervios por superados."},"D1_04_S1a":{"tx":"Al pasar la chincheta, Seoyeon alinea el aviso desde la esquina. Manos que conocen el orden."},"D1_04_S2a":{"tx":"Si quien acaba de llegar es tan rápido, el trabajo de delegada empieza a parecer sospechoso."},"D1_04_S2b":{"tx":"Sospechoso es mucho decir. Aun así, hacerlo en solitario era más de lo que parecía."},"D1_04_C1a":{"tx":"La pregunta sobre gustos se queda un rato en el aire. Ella no apura. Solo ordena los lomos."},"D1_04_C2a":{"tx":"Vendré mañana. Quiero ver qué libros llegan."},"D1_04_C2b":{"tx":"Con esa curiosidad basta. Dejaré libre el asiento de la ventana."},"D1_04_A1a":{"tx":"Se enciende la luz frente al micrófono. Los ojos brillan antes que la pregunta."},"D1_04_A2a":{"tx":"Si esa respuesta no tiene que salir al aire, es un alivio."},"D1_04_A2b":{"tx":"No es un alivio. Es un riesgo. Porque esa respuesta la sé solo yo."},"D2_02_05W":{"tx":"......Si vas a esperar, dilo. Estoy acostumbrada a hacerlo sola, y no sé leer el silencio de al lado."},"D2_02_05W2":{"tx":"Aun así, si estás aquí, las manos se mueven. ¿Miramos juntos el borrador del discurso?"},"D2_04_S1a":{"tx":"Tres días. En el calendario, la casilla del festival está más cerca de lo que parecía."},"D2_04_S2a":{"tx":"La mitad del orden del día de la próxima reunión ya está lista. Solo la parte que leíste."},"D2_04_S2b":{"tx":"Seoyeon tapa el bolígrafo y sonríe, apenas. Una cara que no aparece cuando está sola."},"D2_04_C1a":{"tx":"Solo se oye cómo se alinean los lomos. Ella parece a gusto en ese silencio."},"D2_04_C2a":{"tx":"¿Quito esa estantería? ¿O la dejo así?"},"D2_04_C2b":{"tx":"Déjala. Si la quitas, será como si quien vino hoy no hubiera estado."},"D2_04_A1a":{"tx":"El bolígrafo de Arin se detiene antes de la tercera pregunta. Para un ensayo, la mirada es seria."},"D2_04_A2a":{"tx":"Lo recuerdas, y simplemente no lo sacas al aire."},"D2_04_A2b":{"tx":"Sí. Taché esa página en rojo. Privado. Con trazo grueso."},"D3_02_05N":{"tx":"Avisar también está bien. Pero el comité de la biblioteca soy yo. Buscar juntas es más rápido."},"D3_04_S1a":{"tx":"Nosotras. La palabra se queda antes que la tapa de la caja."},"D3_04_S2a":{"tx":"Revisa la última página. Hoy yo también necesito un segundo par de ojos."},"D3_04_S2b":{"tx":"Con cada sello, los hombros de Seoyeon bajan un poco."},"D3_04_C1a":{"tx":"Huele a polvo. Ella mete la mano en los estantes bajos como si los conociera."},"D3_04_C2a":{"tx":"Este libro irá en el primer lugar de la exposición de mañana. Lo encontramos juntas."},"D3_04_C2b":{"tx":"La cubierta está tibia. Un libro que desapareció y volvió pesa, hoy, extrañamente poco."},"D3_04_A1a":{"tx":"La luz roja vuelve a encenderse. No parece un ensayo."},"D3_04_A2a":{"tx":"Si lo escribes en el cuaderno, ¿se vuelve una promesa de verdad?"},"D3_04_A2b":{"tx":"Sí. El cuaderno del club de radio es un contrato. Aunque se anula si huyes antes de que se seque la tinta."},"D5_02_16L":{"tx":"......Está bien. Ve a lo siguiente. De aquí me encargo yo."},"D5_02_16L2":{"tx":"Los pasos dan la vuelta. El gracias se queda otra vez sin decir."},"D5_03_16L":{"tx":"......Sí, ve. Yo cuido la exposición. Todavía no hay razón para quitarme las gafas."},"D5_03_16L2":{"tx":"El asiento de la ventana sigue siendo para una persona. Hoy esa distancia encaja."},"D5_04_16L":{"tx":"......De acuerdo. El cierre lo hago sola. El espacio en blanco lo dejaré también la próxima vez."},"D5_04_16L2":{"tx":"La puerta del estudio se cierra. La luz de directo sigue encendida."},"D5_05_S3a":{"tx":"Cuando la entrada y la salida se separan, los pasos de la gente caen en una sola dirección."},"D5_05_S3b":{"tx":"Este recorrido coincide con el plano que corregimos ayer entre los dos. El papel se hizo real."},"D5_05_C3a":{"tx":"Alguien frente al tablón lee el aviso en voz alta. Esperar también es parte del festival."},"D5_05_C3b":{"tx":"Oír en otra boca la frase que elegiste es raro. Un raro que no está mal."},"D5_05_A3a":{"tx":"La gente que espera levanta la cabeza con el anuncio. Las dos voces no se pisan. Se siguen."},"D5_05_A3b":{"tx":"Este ritmo quiero usarlo también en la emisión de mañana. Aunque el espacio en blanco ya es tuyo."},"END_SY_G08a":{"tx":"Mañana por la mañana también, en la puerta. Acompañarte quizá ya no sea una excusa."},"END_SY_G08b":{"tx":"La esquina del formulario se levanta con el viento. Los dos nombres aún no se han secado."},"END_SY_N03a":{"tx":"Por la ventana del pasillo se ve cómo pliegan las carpas del festival. Hoy termina aquí."},"END_SY_N03b":{"tx":"Mañana, cada quien con su libro. Si aun así hacen falta los apuntes, dilo."},"END_SY_N03c":{"tx":"Sí. La regla está clara."},"END_SY_N03d":{"tx":"Seoyeon levanta la mano, apenas, y entra primero al aula. La distancia sigue. Mañana también existe."},"END_CH_G06a":{"tx":"Mañana al mediodía abro la caja de novedades. El primer libro lo abrimos juntos."},"END_CH_G06b":{"tx":"No empezaré por la última página. La promesa sigue en pie, ¿verdad?"},"END_CH_G06c":{"tx":"Sigue. Y hoy se le añadió una línea. El asiento de al lado."},"END_CH_N02a":{"tx":"La mano que recibe el marcapáginas es breve y exacta. No retiene más."},"END_CH_N02b":{"tx":"La silla de la ventana mañana también es una. Pero la puerta no la dejaré cerrada."},"END_CH_N02c":{"tx":"Entonces llamaré antes de entrar."},"END_CH_N02d":{"tx":"Llamar está bien. La biblioteca quiere a quien llega en silencio."},"END_CH_N02e":{"tx":"Antes de que se apaguen las luces, miro atrás una vez más. El asiento sigue siendo para una persona."},"END_AR_G05a":{"tx":"La apertura de la emisión de mañana es tuya. Si llegas tarde, borro el espacio en blanco."},"END_AR_G05b":{"tx":"Llegaré temprano, para que no lo borres."},"END_AR_G05c":{"tx":"El cuaderno se cierra con un sonido pequeño. La palabra «confirmado» ya está oscura."},"END_AR_N02a":{"tx":"Arin se quita del cuello la tarjeta de miembro y la deja en el escritorio. La emisión ha terminado."},"END_AR_N02b":{"tx":"La segunda entrevista queda en espera. No es la reserva. Es que aún no me sale la siguiente pregunta."},"END_AR_N02c":{"tx":"Cuando salga, dilo entonces."},"END_AR_N02d":{"tx":"Lo diré. Por el canal oficial. Los mensajes personales... hoy me contengo."},"END_AR_N02e":{"tx":"Ella hace un saludo breve y vuelve a guardar el equipo. El cuaderno sigue cerrado."},"END_SOLO_04a":{"tx":"En los mensajes solo quedan saludos cortos. Ninguna frase es lo bastante gruesa para llamarla promesa."},"END_SOLO_04b":{"tx":"Nadie dejó libre el asiento de al lado. A cambio, un día de escuela ya cabe en las manos."},"END_SOLO_04c":{"tx":"Al salir por la puerta, un pensamiento: la próxima vez después de clase, se puede elegir un poco más cerca."},"N2_03G":{"tx":"(Mensaje) Buen trabajo hoy también. Mañana por la mañana, en el aula."},"N2_04G":{"tx":"Un saludo corto. Y, por alguna razón, la respuesta no sale enseguida."},"N2_06G":{"tx":"(Mensaje) Mañana también escucha la emisión del mediodía. Huir sigue prohibido."},"N3_03G":{"tx":"(Mensaje) Buen trabajo hoy también. El plazo del compañero es hasta mañana. No te fuerces. Duerme."},"N3_04G":{"tx":"(Mensaje) Si oyes la emisión de mañana, solo saluda con la mano. Por hoy, hasta aquí."},"D4_05_S1a":{"tx":"La punta del bolígrafo se detiene en la última casilla. Seoyeon mira hacia aquí antes de escribir un nombre."},"D4_05_S2a":{"tx":"No es una obligación. Pero si se queda en blanco, creo que volveré a llenarlo sola."},"D4_05_S2b":{"tx":"Al final de esa frase se engancha, apenas, el apoyarse que hoy aprendió."},"D4_05_C1a":{"tx":"En el letrero del primer libro hay una frase corta. La primera página, abierta juntos."},"D4_05_C2a":{"tx":"Aunque no vengas, la exposición sigue. Pero esa silla la pongo pensando en ti."},"D4_05_C2b":{"tx":"No es un tono que se rechace. Quieto, pero cada frase deja un asiento libre."},"D4_05_A1a":{"tx":"La luz de directo está apagada, pero la voz de Arin ya está en antena."},"D4_05_A2a":{"tx":"El espacio en blanco aún no está fijado. Mañana por la mañana, puede que lo deje en tinta."},"D4_05_A2b":{"tx":"Lo dice como una broma, pero la esquina del cuaderno está doblada. Esa página se abrió muchas veces."}}};
